/// `skip_serializing_if` helper for `bool` fields with `omitempty`.
pub(crate) fn is_false(b: &bool) -> bool {
    !*b
}

/// `skip_serializing_if` helper for numeric fields with `omitempty`.
pub(crate) fn is_zero<T: Default + PartialEq>(v: &T) -> bool {
    *v == T::default()
}
pub mod error {
//! Error types for the LXD client.
use thiserror::Error;

/// Errors returned by the LXD client.
#[derive(Debug, Error)]
pub enum LxdError {
    /// HTTP transport failure (connection, TLS, timeout, ...).
    #[error("transport error: {0}")]
    Transport(#[from] reqwest::Error),

    /// The server returned an error response envelope.
    #[error("LXD API error {code}: {message}")]
    Api {
        /// LXD error code (`error_code` in the envelope).
        code: i64,
        /// Human readable error message.
        message: String,
    },

    /// The requested resource was not found (HTTP 404).
    #[error("not found: {0}")]
    NotFound(String),

    /// Authentication failed (HTTP 401) or the server rejected the credentials.
    #[error("authentication failed: {0}")]
    Auth(String),

    /// The server response could not be understood.
    #[error("invalid response: {0}")]
    InvalidResponse(String),

    /// JSON (de)serialization failure.
    #[error("serialization error: {0}")]
    Serde(#[from] serde_json::Error),

    /// The base URL was invalid.
    #[error("invalid URL: {0}")]
    Url(#[from] url::ParseError),

    /// The requested operation is not supported by this client
    /// (e.g. websocket-backed exec/console, SFTP, live migration).
    #[error("unsupported operation: {0}")]
    Unsupported(String),

    /// The operation finished with an error status.
    #[error("operation failed: {0}")]
    OperationFailed(String),
}

impl LxdError {
    /// Build an [`LxdError::Api`] from an envelope's error fields.
    pub fn api(code: i64, message: impl Into<String>) -> Self {
        Self::Api {
            code,
            message: message.into(),
        }
    }
}
}
