/// A strictly-typed JSON value for genuinely open-ended LXD payload fields
/// (Go `any` / `map[string]any`), e.g. operation metadata and event context.
///
/// This is a closed recursive enum over JSON's six value kinds — it is not
/// an untyped bag: every variant is concrete.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(untagged)]
pub enum JsonValue {
    /// JSON null.
    Null,
    /// JSON boolean.
    Bool(bool),
    /// JSON number (integer or float, preserved exactly).
    Number(serde_json::Number),
    /// JSON string.
    String(String),
    /// JSON array.
    Array(Vec<JsonValue>),
    /// JSON object.
    Object(HashMap<String, JsonValue>),
}

impl Default for JsonValue {
    fn default() -> Self {
        Self::Null
    }
}

impl JsonValue {
    /// Convenience: interpret the value as a string, if it is one.
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Self::String(s) => Some(s),
            _ => None,
        }
    }

    /// Convenience: interpret the value as a bool, if it is one.
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Self::Bool(b) => Some(*b),
            _ => None,
        }
    }
}

