pub mod state_plugin {
//! Standalone LXD plugin schema (opdbus plugin pattern, standalone form).
//!
//! This module is the single typed present-state/control contract for LXD:
//! [`LxdState`] is the present-state document, the per-method Input/Output
//! pairs live in [`crate::state_plugins::lxd::methods`], [`crate::state_plugins::lxd::dispatch::dispatch_lxd_method`]
//! is the typed entry point, and [`lxd_schema()`] builds the sealed schema
//! document (state + methods + capabilities) that a plugin seals into a blob.
//!
//! The crate is standalone: the user's internal crates (`op_state`,
//! `op_state_store`, `schemars_adapter`) are NOT available here, so the
//! schema document is the serializable [`PluginSchemaDoc`] (plain JSON),
//! not `op_state_store::PluginSchema`. The marked `OP_STATE WIRING` section
//! at the end of this file says exactly where the direct `impl StatePlugin`
//! wiring drops in once those crates are available. No `op_state` types
//! are invented here.
//!
//! Deterministic and sealable: the schema document is built fresh from the
//! types on every call (no stored copy, no cache, no timestamps, no live
//! data), methods and capabilities are `BTreeMap`s (stable order), and the
//! document's subschemas are inlined, so the sealed unit (`plugin.json`,
//! written by [`write_plugin_json`]) is self-contained. See the
//! determinism test in `tests/plugin_smoke.rs`.
//!
//! Fail closed: state and method schemas are the single source of truth.
//! A method call returns its typed Output directly as the response — there
//! is no acknowledgement step, no ack field, no ack round-trip.

use crate::state_plugins::lxd::client_extra::Client;
use crate::state_plugins::lxd::error::LxdError;
use crate::state_plugins::lxd::types::{
    Image, Instance, Network, Operation, Profile, Project, Server, StoragePool,
    StorageVolume, Warning,
};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

/// Plugin name, as registered in the schema document and capabilities.
pub const PLUGIN_NAME: &str = "lxd";
/// Plugin version (the crate version).
pub const PLUGIN_VERSION: &str = env!("CARGO_PKG_VERSION");
/// OSCAL category for this plugin (matches the incus plugin's category).
pub const PLUGIN_CATEGORY: &str = "service";
/// Human-readable description of the plugin.
pub const PLUGIN_DESCRIPTION: &str =
    "LXD instance, image, network, storage, profile and project management over the LXD API";
/// Display name for the plugin.
pub const PLUGIN_DISPLAY_NAME: &str = "LXD";

/// Top-level present-state contract for LXD: the single typed document
/// describing what exists on the server.
///
/// Deterministic and offline-reproducible: no live probes or credentials
/// are allowed in state. The document is populated by observation (the
/// `get_*` methods), never by declaration — [`LxdState::empty()`] is the
/// unobserved state, and every resource list is empty until observed.
/// The fixed identity fields (`software`, `plugin_version`) are listed in
/// `x-immutable-paths`: they never change for a given plugin build.
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema, PartialEq)]
#[schemars(extend("x-oscal-subid" = "sch.service.plugin.lxd.schema@v1"))]
#[schemars(extend("x-oscal-category" = "service"))]
#[schemars(extend("x-immutable-paths" = ["software", "plugin_version"]))]
pub struct LxdState {
    /// Plugin software name (`"lxd"`).
    pub software: String,
    /// Plugin version.
    pub plugin_version: String,
    /// Server info, when observed (`get_server`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub server: Option<Server>,
    /// Instances, when observed (`get_instances`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub instances: Vec<Instance>,
    /// Images, when observed (`get_images`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub images: Vec<Image>,
    /// Networks, when observed (`get_networks`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub networks: Vec<Network>,
    /// Storage pools, when observed (`get_storage_pools`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub storage_pools: Vec<StoragePool>,
    /// Storage volumes, when observed (`get_storage_pool_volumes`).
    /// Each volume carries its pool name.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub storage_volumes: Vec<StorageVolume>,
    /// Profiles, when observed (`get_profiles`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub profiles: Vec<Profile>,
    /// Projects, when observed (`get_projects`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub projects: Vec<Project>,
    /// Operations, when observed (`get_operations`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub operations: Vec<Operation>,
    /// Warnings, when observed (`get_warnings`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub warnings: Vec<Warning>,
}

impl LxdState {
    /// The unobserved state: fixed identity fields set, every resource
    /// list empty. Observations fill the lists in; nothing is probed here.
    pub fn empty() -> Self {
        Self {
            software: PLUGIN_NAME.to_string(),
            plugin_version: PLUGIN_VERSION.to_string(),
            ..Default::default()
        }
    }
}

/// What a method does to state: read-only observation, or a mutation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum SideEffect {
    /// Read-only observation; the call changes no state.
    Read,
    /// Changes state on the server.
    Mutation,
}

/// One method's declaration in the sealed schema document.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq)]
pub struct MethodDecl {
    /// Dispatch name, e.g. `"get_instance"`.
    pub name: String,
    /// Read or Mutation.
    pub side_effect: SideEffect,
    /// Whether repeating the call with the same input is a no-op.
    pub idempotent: bool,
    /// Capability ID granting the call, e.g. `cap.lxd.instances.get_instance@v1`.
    pub capability: String,
    /// OSCAL subid for the observation/mutation, e.g. `obs.lxd.instances.get_instance@v1`.
    pub subid: String,
    /// JSON Schema of the method's Input type.
    pub input: serde_json::Value,
    /// JSON Schema of the method's Output type.
    pub output: serde_json::Value,
}

/// One capability declaration in the sealed schema document.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
pub struct CapabilityDecl {
    /// Capability ID, e.g. `cap.lxd.instances.get_instance@v1`.
    pub id: String,
    /// What the capability grants.
    pub description: String,
}

/// One event signal declaration in the sealed schema document.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq)]
pub struct SignalDecl {
    /// Signal name.
    pub name: String,
    /// JSON Schema of the signal payload, when the signal carries one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub payload: Option<serde_json::Value>,
    /// OSCAL subid for the signal.
    pub subid: String,
}

/// The sealed plugin schema document: state + methods + capabilities in
/// one self-contained unit, ready to pack into a blob.
///
/// This is the standalone equivalent of `op_state_store::PluginSchema`:
/// plain serializable JSON with the same shape (name, version, category,
/// display name, state schema, methods with input/output schemas,
/// capabilities, signals). It is built fresh from the types on every call
/// by [`lxd_schema()`]; there is no stored copy to go stale.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq)]
pub struct PluginSchemaDoc {
    /// Plugin name (`"lxd"`).
    pub name: String,
    /// Plugin version.
    pub version: String,
    /// OSCAL category (`"service"`).
    pub category: String,
    /// Display name (`"LXD"`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub display_name: Option<String>,
    /// Human-readable description.
    pub description: String,
    /// JSON Schema of the state struct ([`LxdState`]).
    pub state: serde_json::Value,
    /// Methods by dispatch name.
    pub methods: BTreeMap<String, MethodDecl>,
    /// Capabilities by capability ID.
    pub capabilities: BTreeMap<String, CapabilityDecl>,
    /// Event signals. Empty: this crate models no event surface — the
    /// LXD event stream is websocket-only and is left out under the
    /// existence rule (no typed schema, so it does not exist here).
    pub signals: Vec<SignalDecl>,
    /// Example state (the empty observation).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub example: Option<serde_json::Value>,
}

/// Register one method on a schema document, with its Input/Output
/// schemas, side effect, idempotence, capability and subid.
///
/// Mirrors the `add_method` helper in the user's emqx plugin: the
/// capability description is `Grants: <method>.`
pub(crate) fn add_method<I, O>(
    doc: &mut PluginSchemaDoc,
    name: &str,
    side_effect: SideEffect,
    idempotent: bool,
    capability: &str,
    subid: &str,
) where
    I: JsonSchema,
    O: JsonSchema,
{
    doc.methods.insert(
        name.to_string(),
        MethodDecl {
            name: name.to_string(),
            side_effect,
            idempotent,
            capability: capability.to_string(),
            subid: subid.to_string(),
            input: serde_json::to_value(schemars::schema_for!(I))
                .expect("method input schema serializes"),
            output: serde_json::to_value(schemars::schema_for!(O))
                .expect("method output schema serializes"),
        },
    );
    doc.capabilities.insert(
        capability.to_string(),
        CapabilityDecl {
            id: capability.to_string(),
            description: format!("Grants: {name}."),
        },
    );
}

/// Build the standalone JSON schema document (intermediate).
/// Method/capability OSCAL subids are already attached by
/// [`register_plugin_methods`]; schema-level OSCAL is applied when
/// [`lxd_schema`] runs this through `schemars_adapter`.
pub fn lxd_schema_doc() -> PluginSchemaDoc {
    let state = serde_json::to_value(schemars::schema_for!(LxdState))
        .expect("LXD state schema serializes");
    let mut doc = PluginSchemaDoc {
        name: PLUGIN_NAME.to_string(),
        version: PLUGIN_VERSION.to_string(),
        category: PLUGIN_CATEGORY.to_string(),
        display_name: Some(PLUGIN_DISPLAY_NAME.to_string()),
        description: PLUGIN_DESCRIPTION.to_string(),
        state,
        methods: BTreeMap::new(),
        capabilities: BTreeMap::new(),
        signals: Vec::new(),
        example: Some(
            serde_json::to_value(LxdState::empty()).expect("empty LXD state serializes"),
        ),
    };
    crate::state_plugins::lxd::dispatch::register_plugin_methods(&mut doc);
    doc
}

fn json_to_simd(value: &serde_json::Value) -> simd_json::OwnedValue {
    let bytes = serde_json::to_vec(value).expect("json value serializes");
    let mut bytes = bytes;
    simd_json::to_owned_value(&mut bytes).expect("json value converts to simd_json")
}

/// Build the sealed `lxd` [`op_state_store::PluginSchema`].
///
/// OSCAL lands automatically via `schemars_adapter::plugin_schema_from_json`
/// (`x-oscal-subid` / `x-oscal-category` on [`LxdState`], plus derived
/// `__schema__` subid) and via method `cap.*` / `obs.*` / `mut.*` subids
/// registered by [`register_plugin_methods`].
/// Seal-safe state shape for PluginSchema. Nested LXD API types carry
/// nullable map/array items that `prepare_state_schema` rejects; method
/// Input/Output schemas keep the full typed surface. OSCAL on this root
/// still flows through `schemars_adapter` automatically.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq)]
#[schemars(extend("x-oscal-subid" = "sch.service.plugin.lxd.schema@v1"))]
#[schemars(extend("x-oscal-category" = "service"))]
#[schemars(extend("x-immutable-paths" = ["software", "plugin_version"]))]
struct LxdSealState {
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.software@v1"))]
    software: String,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.plugin-version@v1"))]
    plugin_version: String,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.instance-count@v1"))]
    instance_count: u64,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.image-count@v1"))]
    image_count: u64,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.network-count@v1"))]
    network_count: u64,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.storage-pool-count@v1"))]
    storage_pool_count: u64,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.profile-count@v1"))]
    profile_count: u64,
    #[schemars(extend("x-oscal-subid" = "obs.service.plugin.lxd.project-count@v1"))]
    project_count: u64,
}

impl LxdSealState {
    fn empty() -> Self {
        Self {
            software: PLUGIN_NAME.to_string(),
            plugin_version: PLUGIN_VERSION.to_string(),
            instance_count: 0,
            image_count: 0,
            network_count: 0,
            storage_pool_count: 0,
            profile_count: 0,
            project_count: 0,
        }
    }
}

pub fn lxd_schema() -> op_state_store::PluginSchema {
    let doc = lxd_schema_doc();
    let seal_root = serde_json::to_value(schemars::schema_for!(LxdSealState))
        .expect("LXD seal state schema serializes");
    let mut schema = crate::state_plugins::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME,
        PLUGIN_VERSION,
        PLUGIN_DESCRIPTION,
        &seal_root,
    );
    schema.category = PLUGIN_CATEGORY.to_string();
    schema.display_name = doc.display_name.clone();
    schema.tags = vec!["service".into(), "lxd".into(), "instance".into()];
    let example = json_to_simd(
        &serde_json::to_value(LxdSealState::empty()).expect("empty LXD seal state serializes"),
    );
    crate::state_plugins::schemars_adapter::apply_state_defaults(&mut schema, &example);
    schema.example = Some(example);
    for (name, method) in doc.methods {
        let side_effect = match method.side_effect {
            SideEffect::Read => op_state_store::SideEffect::Read,
            SideEffect::Mutation => op_state_store::SideEffect::Mutation,
        };
        schema.methods.insert(
            name,
            op_state_store::MethodDecl {
                name: method.name,
                args: json_to_simd(&method.input),
                returns: Some(json_to_simd(&method.output)),
                side_effect,
                idempotent: method.idempotent,
                required_capability: Some(method.capability.clone()),
                subid: method.subid,
            },
        );
    }
    for (id, cap) in doc.capabilities {
        schema.capabilities.insert(
            id,
            op_state_store::CapabilityDecl {
                id: cap.id,
                description: cap.description,
            },
        );
    }
    for signal in doc.signals {
        schema.signals.push(op_state_store::SignalDecl {
            name: signal.name,
            payload: signal.payload.as_ref().map(json_to_simd),
            subid: signal.subid,
        });
    }
    schema
}

/// Pretty JSON of the sealed schema document (deterministic).
pub fn lxd_schema_json() -> String {
    serde_json::to_string_pretty(&lxd_schema_doc()).expect("lxd schema serializes")
}

/// Write the ONE sealed schema file for this plugin into `out_dir`.
pub fn write_plugin_json(
    out_dir: &std::path::Path,
) -> Result<std::path::PathBuf, Box<dyn std::error::Error>> {
    std::fs::create_dir_all(out_dir)?;
    for entry in std::fs::read_dir(out_dir)? {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.ends_with(".json") && name != "plugin.json" {
            std::fs::remove_file(entry.path())?;
        }
    }
    let text = serde_json::to_string_pretty(&lxd_schema_doc())?;
    let path = out_dir.join("plugin.json");
    std::fs::write(&path, format!("{text}\n"))?;
    Ok(path)
}

/// Schema/inventory plugin handle (no live LXD client required to seal).
#[derive(Debug, Default, Clone)]
pub struct LxdPlugin;

impl LxdPlugin {
    pub fn new() -> Self {
        Self
    }

    pub fn empty_state() -> LxdState {
        LxdState::empty()
    }
}

/// Live dispatch handle wrapping a configured [`Client`].
#[derive(Debug, Clone)]
pub struct LxdDispatch {
    client: Client,
}

impl LxdDispatch {
    pub fn new(client: Client) -> Self {
        Self { client }
    }

    pub fn client(&self) -> &Client {
        &self.client
    }

    pub async fn dispatch(
        &self,
        method: &str,
        args: &serde_json::Value,
    ) -> Result<serde_json::Value, LxdError> {
        crate::state_plugins::lxd::dispatch::dispatch_lxd_method(&self.client, method, args).await
    }
}

#[async_trait::async_trait]
impl op_state::StatePlugin for LxdPlugin {
    fn name(&self) -> &str {
        PLUGIN_NAME
    }

    fn version(&self) -> &str {
        PLUGIN_VERSION
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(lxd_schema())
    }

    async fn calculate_diff(
        &self,
        _current: &simd_json::OwnedValue,
        _desired: &simd_json::OwnedValue,
    ) -> anyhow::Result<op_state::StateDiff> {
        Ok(op_state::StateDiff {
            plugin: PLUGIN_NAME.to_string(),
            actions: vec![],
            metadata: op_state::DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(
        &self,
        _diff: &op_state::StateDiff,
    ) -> anyhow::Result<op_state::ApplyResult> {
        Ok(op_state::ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &simd_json::OwnedValue) -> anyhow::Result<bool> {
        let empty = json_to_simd(
            &serde_json::to_value(LxdSealState::empty()).expect("empty LXD seal state serializes"),
        );
        Ok(&empty == desired)
    }

    async fn create_checkpoint(&self) -> anyhow::Result<op_state::Checkpoint> {
        Ok(op_state::Checkpoint {
            id: format!("{PLUGIN_NAME}-checkpoint"),
            plugin: PLUGIN_NAME.to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: json_to_simd(
                &serde_json::to_value(LxdSealState::empty()).expect("empty LXD seal state serializes"),
            ),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &op_state::Checkpoint) -> anyhow::Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> op_state::PluginCapabilities {
        op_state::PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

inventory::submit! {
    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| {
        std::sync::Arc::new(LxdPlugin::new())
    })
}
}

